import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';

export default function Profile() {
  const { user } = useAuth();
  const [editing, setEditing] = useState(false);
  const [form, setForm] = useState({});
  const [availableMatieres, setAvailableMatieres] = useState([]);
  const [saved, setSaved] = useState(false);

  useEffect(() => {
    // 1. Charger mes données (selon le rôle)
    const route = user?.role === 'professeur' ? '/api/professeurs/me' : '/api/etudiants/me';
    api.get(route).then(r => setForm(r.data)).catch(() => {});

    // 2. Si prof, charger la liste des matières possibles (Admin)
    if (user?.role === 'professeur') {
        api.get('/api/admin/referentiel/matieres').then(r => setAvailableMatieres(r.data)).catch(() => {});
    }
  }, [user]);

  // Fonction pour mettre à jour un tarif spécifique (Image 3 & 4)
  const handleTarifChange = (matiere_id, tarif) => {
    const updatedTarifs = [...(form.tarifs_matieres || [])];
    const index = updatedTarifs.findIndex(t => t.matiere_id === matiere_id);

    if (index > -1) {
      updatedTarifs[index].tarif = tarif;
    } else {
      updatedTarifs.push({ matiere_id, tarif });
    }
    setForm({ ...form, matieres_avec_tarifs: updatedTarifs });
  };

  async function handleSave() {
    try {
      const route = user?.role === 'professeur' ? '/api/professeurs/me' : '/api/etudiants/me';
      await api.put(route, form);
      setSaved(true); setTimeout(() => setSaved(false), 2000);
      setEditing(false);
    } catch (e) { alert('Erreur sauvegarde'); }
  }

  const inp = { background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 10, color: 'var(--text)', padding: '10px 14px', fontSize: '.88rem', outline: 'none', width: '100%' };

  return (
    <div style={{ padding: 32, maxWidth: 1000, margin: '0 auto' }}>
      <div style={{ fontFamily: 'Syne', fontSize: '1.5rem', fontWeight: 700, marginBottom: 24 }}>⚙️ Paramètres du compte</div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 30 }}>

        {/* COLONNE GAUCHE : IDENTITÉ (Image 1) */}
        <div>
          <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 16, padding: 24 }}>
            <div style={{ fontWeight: 600, marginBottom: 20 }}>👤 Informations personnelles</div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 15 }}>
               <div>
                 <label style={{fontSize: '.8rem', color: 'var(--text2)'}}>Prénom & Nom</label>
                 <div style={{fontWeight: 600}}>{form.user_prenom} {form.user_nom}</div>
               </div>
               <div>
                 <label style={{fontSize: '.8rem', color: 'var(--text2)'}}>Email</label>
                 <div style={{fontWeight: 500}}>{form.email}</div>
               </div>
               <div>
                 <label style={{fontSize: '.8rem', color: 'var(--text2)'}}>Ville</label>
                 <input style={inp} value={form.ville || ''} onChange={e => setForm({...form, ville: e.target.value})} />
               </div>
               <button onClick={handleSave} style={{ background: 'var(--accent)', color: '#fff', border: 'none', padding: 12, borderRadius: 10, fontWeight: 600, marginTop: 10 }}>Enregistrer les modifications</button>
            </div>
          </div>

          {/* SECTION CERTIFICATS (Image 2) */}
          {user?.role === 'professeur' && (
            <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 16, padding: 24, marginTop: 24 }}>
                <div style={{ fontWeight: 600, marginBottom: 16 }}>📜 Certificats et Diplômes</div>
                <div style={{ display: 'grid', gap: 12 }}>
                    {form.certificats?.map(c => (
                        <div key={c.id} style={{ background: 'var(--surface2)', padding: 12, borderRadius: 10, border: '1px solid var(--border)' }}>
                            <div style={{ fontWeight: 600, fontSize: '.9rem' }}>{c.titre}</div>
                            <a href={`http://localhost:8001${c.fichier_url}`} target="_blank" style={{ color: 'var(--accent)', fontSize: '.8rem' }}>Voir le document ↗</a>
                        </div>
                    ))}
                    <button style={{ border: '2px dashed var(--border)', background: 'none', color: 'var(--text2)', padding: 15, borderRadius: 12, cursor: 'pointer' }}>+ Ajouter un diplôme</button>
                </div>
            </div>
          )}
        </div>

        {/* COLONNE DROITE : MATIÈRES ET TARIFS (Image 3 & 4) */}
        {user?.role === 'professeur' && (
          <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 16, padding: 24 }}>
            <div style={{ fontWeight: 600, marginBottom: 16 }}>📚 Matières enseignées & Tarifs</div>
            <p style={{ fontSize: '.85rem', color: 'var(--text2)', marginBottom: 20 }}>Cochez les matières et indiquez votre tarif horaire.</p>

            <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
                {availableMatieres.map(m => {
                    const activeTarif = form.tarifs_matieres?.find(t => t.matiere_id === m.id);
                    return (
                        <div key={m.id} style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '10px 15px', background: activeTarif ? 'rgba(108,99,255,.05)' : 'transparent', borderRadius: 10, border: '1px solid var(--border)' }}>
                            <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                                <input type="checkbox" checked={!!activeTarif} onChange={() => {/* Logique Toggle */}} />
                                <span style={{ fontSize: '.9rem' }}>{m.nom}</span>
                            </div>
                            {activeTarif && (
                                <div style={{ display: 'flex', alignItems: 'center', gap: 5 }}>
                                    <input type="number" value={activeTarif.tarif} onChange={(e) => handleTarifChange(m.id, e.target.value)} style={{ ...inp, width: 60, padding: '4px' }} />
                                    <span style={{ fontSize: '.75rem' }}>DT/h</span>
                                </div>
                            )}
                        </div>
                    )
                })}
            </div>
          </div>
        )}

      </div>
    </div>
  );
}
